"""Authored bilingual learning views; measurements are loaded from audited records."""
import html


def bulkhead(lang):
    t=lambda en,zh:zh if lang=='zh' else en
    return f'''<section class="hero"><div><p class="eyebrow">Java Runtime Lab / 02</p><h1>{t('Cheap threads.<br>Finite downstream.','线程便宜。<br>下游有限。')}</h1><p class="lede">{t('12 real virtual-thread tasks, 3 declared downstream slots. Compare admission policies, then follow a cancelled permit holder.','12 个真实虚拟线程任务，3 个下游槽位。对比准入策略，再跟踪被取消的许可持有者。')}</p></div><aside class="note"><strong>{t('Predict → run → challenge','预测 → 实跑 → 质疑')}</strong><p>{t('Saved actual JDK 25 runs. A latch forces overlap; no random curve or browser engine. This is a resource-lifecycle experiment, not a throughput ranking.','保存的真实 JDK 25 运行。门闩强制重叠，没有随机曲线或浏览器引擎。这是资源生命周期实验，不是吞吐排名。')}</p><a href="../curriculum/#capacity">{t('Run the original exercise →','运行原创练习 →')}</a></aside></section>
<div class="toolbar"><label>{t('Saved run','保存轮次')}<select id="run"><option value="1">01</option><option value="2">02</option><option value="3">03</option></select></label><button id="download">{t('Download run JSON','下载整轮 JSON')}</button><button id="share">{t('Copy deep link','复制分享深链')}</button></div>
<p id="status" class="status" role="status" aria-live="polite">{t('Loading recorded evidence…','正在加载实测记录…')}</p>
<section class="workspace" id="workspace"><h2>{t('Inspect the downstream boundary','检查下游边界')}</h2><div class="toolbar"><label>{t('Admission / cancellation','准入 / 取消策略')}<select id="policy"></select></label><button id="export-case">{t('Export complete case','导出完整案例')}</button></div><div id="metrics" class="metrics"></div><div id="chart"></div><p id="explanation" class="lede"></p><div id="comparison"></div><details open><summary>{t('Task and resource transitions','任务与资源转换')}</summary><div class="toolbar"><label>{t('Task filter','任务筛选')}<select id="task"></select></label><small id="event-count"></small></div><div id="events" class="trace"></div></details><details><summary>{t('Actual JFR counts and capture contract','真实 JFR 计数与采集契约')}</summary><pre id="jfr"></pre></details></section>
<article class="reading"><h2>{t('What the controls establish','对照验证了什么')}</h2><p>{t('Unbounded is a counterexample: virtual threads alone do not enforce the declared resource capacity. Queue and reject use real Semaphore permits. The queued count is the number registered as waiting, not a sample of the JVM’s internal queue. The waiting policy has no independent queue-size limit; this burst is finite.','无限制策略是反例：单靠虚拟线程不会执行声明的资源容量限制。等待与拒绝使用真实 Semaphore 许可。queued 是登记等待的数量，不是 JVM 内部队列采样。等待策略没有独立队列长度上限，本实验的突发请求是有限的。')}</p><p>{t('A queued cancellation must never enter downstream. A cooperative holder exits and returns its permit. The ignore-interrupt control remains active even after Future cancellation; its gate is then released and all permits must return. “Cancelled” counts interrupted task lifecycles, including that finite control.','等待中取消不得进入下游。协作持有者退出并归还许可。忽略中断的对照在 Future 取消后仍活跃，随后释放门闩并检查全部许可归还。“cancelled”统计观察到中断的任务生命周期，也包含这个有限对照。')}</p><p>{t('JEP 491 removed synchronized-related pinning in JDK 24. The pinned-event count below is only what this workload recorded. No event is invented and no absence is treated as proof. Structured concurrency remains optional preview reading; this Lab does not enable preview.','JEP 491 在 JDK 24 消除了 synchronized 相关 pinning。下方 pinned 计数仅代表本负载的采集结果，不虚构事件，也不以缺失作证明。结构化并发仅作可选 preview 阅读，本实验未启用 preview。')}</p><p><a href="../methods/">{t('Exact protocol, oracle and limitations →','精确协议、独立 oracle 与边界 →')}</a> · <a href="../curriculum/">{t('Six executable learning units →','六个可执行学习单元 →')}</a></p></article>
<noscript><p class="note">{t('Read the protocol and download the actual records directly. The viewer needs JavaScript.','可直接阅读协议与下载真实记录，查看器需要 JavaScript。')} <a href="../../assets/bulkhead-1.json">bulkhead-1.json</a></p></noscript>'''


def curriculum(lang,data):
    t=lambda en,zh:zh if lang=='zh' else en
    e=html.escape
    resources={r['id']:r for r in data['resources']}
    body=f'''<article class="reading"><p class="eyebrow">Java Runtime Lab / curriculum</p><h1>{t('Learn it. Run it. Explain it.','学过，跑通，解释清楚。')}</h1><p class="lede">{e(data['scope'][lang])}</p><p class="note">{t('Verified 14 November 2026. Historical course materials and published JDK documents are distinguished from optional preview reading. No planned course is presented as available.','核验日期：2026 年 11 月 14 日。历史课程、已发布 JDK 文档与可选 preview 阅读分别标注；不把计划课程说成已开放。')}</p><p><a href="../../assets/curriculum.json" download>{t('Download searchable registry JSON','下载结构化资源清单 JSON')}</a> · <a href="../../assets/resource-checks.json">{t('Anonymous source-access receipts','匿名资料访问核验记录')}</a></p><label for="resource-search">{t('Search course, source, topic or command','搜索课程、来源、主题或命令')}</label><input id="resource-search" type="search" placeholder="{t('Try cancellation, JFR, 6.172…','例如 取消、JFR、6.172…')}"><p id="search-status" class="status" role="status" aria-live="polite"></p><h2>{t('Selected course and access','精选课程与访问条件')}</h2>'''
    for c in data['courses']:
        body+=f'''<section class="card" data-search="{e(str(c),quote=True)}"><h3><a href="{e(c['url'])}">{e(c['school'])} · {e(c['courseNumber'])} · {e(c['name'])}</a></h3><p>{e(c['semester'])} · {t('Language','课程语言')}: {e(c['language'])} · {t('Verified','核验')}: {e(c['verifiedOn'])}</p><p>{t('Prerequisites','先修')}: {e('; '.join(c['prerequisites']))}</p><p>{e(c['fit'][lang])}</p><p>{t('Public reading: archived OCW slides, videos, readings and assignments require no account or payment. Reading does not enroll you at MIT or award credit/certificates. Campus admission, registration and tuition are separate; this Lab makes no enrollment offer.','公开阅读：归档 OCW 讲义、视频、阅读与作业不需注册或付费。阅读不等于 MIT 注册学生，也不授予学分或证书。校园招生、选课和学费是另一回事，本实验不提供注册服务。')}</p></section>'''
    body+=f'<h2>{t("Six original executable exercises","六个原创可执行练习")}</h2><p>{t("Run doctor → build first. Each command starts real Java locally, checks the complete recording, then reports one focused question. Use --record with a matching saved JSON to inspect without rerunning. No API key is needed.","先执行 doctor → build。每个命令在本地启动真实 Java、核验完整记录，再围绕一个问题输出结果。使用 --record 和相应保存 JSON 可只检查记录。无需 API key。")}</p>'
    for u in data['units']:
        links=' · '.join(f'<a href="{e(resources[id]["url"])}">{e(resources[id]["title"])}</a>' for id in u['resourceIds'])
        body+=f'''<section class="learning-unit" id="{u['id']}" data-search="{e(str(u),quote=True)}"><h3>{e(u['title'][lang])}</h3><p>{links}</p><p><strong>{t('Predict','先预测')}:</strong> {e(u['predict'][lang])}</p><pre><code>{e(u['command'])}</code></pre><p><strong>{t('Inspect and explain','观察并解释')}:</strong> {e(u['observe'][lang])}</p><p class="note">{e(u['boundary'][lang])}</p></section>'''
    body+=f'<h2>{t("Primary-source registry","原始资料清单")}</h2>'
    for r in data['resources']:
        body+=f'''<section class="resource" data-search="{e(str(r),quote=True)}"><h3><a href="{e(r['url'])}">{e(r['title'])}</a></h3><p>{e(r['section'])}</p><p class="meta">{e(r['kind'])} · {e(r['status'])} · {t('Verified','核验')}: {e(r['verifiedOn'])}</p></section>'''
    body+=f'''<p>{t('The Vanderbilt item is a 2020 PDF from the instructor archive; the linked landing pages do not establish an exact semester for that PDF. It is supplementary reading, not a second selected course or a current enrollment offer. JEP 444 describes JDK 21 historical pinning behavior; use JEP 491 and the JDK 25 guide for this pinned runtime.','Vanderbilt 项目是教师归档中的 2020 PDF，所连页面未明确该 PDF 的学期，因此只作补充阅读，不冒充第二门精选课程或当前招生项目。JEP 444 描述的是 JDK 21 历史 pinning 行为；本实验固定版本应结合 JEP 491 与 JDK 25 指南阅读。')}</p><h2>{t('Transfer to an AI service','迁移到 AI 服务场景')}</h2><p>{t('Treat each synthetic downstream slot as an in-flight inference request, connection or local accelerator slot. The learning goal is to enforce concurrency and release resources when work actually exits. This model does not evaluate model quality, tokens per second, provider rate limits, networking or billing. No model or paid API is called.','可把每个合成下游槽位理解为一个在途推理请求、连接或本地加速器槽位。学习目标是限制并发，并在实际工作退出时归还资源。本模型不评测模型质量、token 吞吐、供应商限流、网络或账单，也不调用模型或付费 API。')}</p><p><a href="../bulkhead/">{t('Inspect actual saved bulkhead evidence →','检查真实 bulkhead 保存记录 →')}</a></p></article>'''
    return body
